(function() {
    'use strict';

    class InsuranceAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'Insurance Underwriting & Portfolio Risk';
            this.version = '1.1.0';
            this.ROUNDS = [
                {
                    briefingKey: 'briefing_q1',
                    baseAutoLoss: 68,
                    basePropertyLoss: 58,
                    baseLiabilityLoss: 65,
                    catEvent: false,
                    catPropertyAdd: 0,
                    catReinsReduction: [0, 0, 0],
                    investYields: [0.035, 0.055, 0.08]
                },
                {
                    briefingKey: 'briefing_q2',
                    baseAutoLoss: 72,
                    basePropertyLoss: 60,
                    baseLiabilityLoss: 67,
                    catEvent: false,
                    catPropertyAdd: 0,
                    catReinsReduction: [0, 0, 0],
                    investYields: [0.035, 0.055, 0.08]
                },
                {
                    briefingKey: 'briefing_q3',
                    baseAutoLoss: 70,
                    basePropertyLoss: 58,
                    baseLiabilityLoss: 68,
                    catEvent: true,
                    catPropertyAdd: 40,
                    catReinsReduction: [0, 0.6, 0.88],
                    investYields: [0.03, 0.01, -0.06]
                },
                {
                    briefingKey: 'briefing_q4',
                    baseAutoLoss: 60,
                    basePropertyLoss: 50,
                    baseLiabilityLoss: 60,
                    catEvent: false,
                    catPropertyAdd: 0,
                    catReinsReduction: [0, 0, 0],
                    investYields: [0.04, 0.065, 0.095]
                }
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    capital: 120,
                    autoGWP: 80,
                    propertyGWP: 70,
                    liabilityGWP: 50,
                    totalGWP: 200,
                    investmentPortfolio: 280,
                    solvencyRatio: 185,
                    lastCombinedRatio: 98.5,
                    reserveDeficitCarry: 0,
                    combinedRatioHistory: [],
                    capitalHistory: [],
                    roeHistory: [],
                    investIncomeHistory: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    autoPriceAdj: 0,
                    propertyPriceAdj: 0,
                    liabilityPriceAdj: 0,
                    reinsurance: 0,
                    reserveApproach: 0,
                    investmentStrategy: 1,
                    dividend: 0
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            var autoSel = document.getElementById('autoPriceSelect');
            if (autoSel) decisions.autoPriceAdj = parseInt(autoSel.value);

            var propSel = document.getElementById('propertyPriceSelect');
            if (propSel) decisions.propertyPriceAdj = parseInt(propSel.value);

            var liabSel = document.getElementById('liabilityPriceSelect');
            if (liabSel) decisions.liabilityPriceAdj = parseInt(liabSel.value);

            var reinsSel = document.getElementById('reinsuranceSelect');
            if (reinsSel) decisions.reinsurance = parseInt(reinsSel.value);

            var resSel = document.getElementById('reserveSelect');
            if (resSel) decisions.reserveApproach = parseInt(resSel.value);

            var invSel = document.getElementById('investmentSelect');
            if (invSel) decisions.investmentStrategy = parseInt(invSel.value);

            var divInput = document.getElementById('dividendInput');
            if (divInput) decisions.dividend = parseFloat(divInput.value) || 0;

            if (decisions.dividend < 0 || decisions.dividend > 20) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('dividend_warning'), 'warning'
                );
                return false;
            }

            var ds = window.mySimulation.state.domainState;
            var reqCap = ds.autoGWP * 0.15 + ds.propertyGWP * 0.25 + ds.liabilityGWP * 0.35;
            if (decisions.dividend > 0 && (ds.capital - decisions.dividend) < reqCap * 1.2) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('solvency_warning'), 'warning'
                );
                return false;
            }

            this._updateBriefing(window.mySimulation.state);
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var roundIdx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[roundIdx];

            var calcLine = function(gwp, priceAdj, baseLoss) {
                var volFactor;
                if (priceAdj <= 0) {
                    volFactor = 1 + (-priceAdj) * 0.007;
                } else {
                    volFactor = 1 - priceAdj * 0.005;
                }
                var newGWP = Math.round(gwp * volFactor * 10) / 10;

                var lossAdj;
                if (priceAdj <= 0) {
                    lossAdj = (-priceAdj) * 0.5;
                } else {
                    lossAdj = -priceAdj * 0.3;
                }
                var lossRatio = Math.round((baseLoss + lossAdj) * 10) / 10;
                return { newGWP: newGWP, lossRatio: lossRatio };
            };

            var autoRes = calcLine(ds.autoGWP, d.autoPriceAdj, round.baseAutoLoss);
            var propRes = calcLine(ds.propertyGWP, d.propertyPriceAdj, round.basePropertyLoss);
            var liabRes = calcLine(ds.liabilityGWP, d.liabilityPriceAdj, round.baseLiabilityLoss);

            if (round.catEvent) {
                var reinsLvl = d.reinsurance || 0;
                var reduction = round.catReinsReduction[reinsLvl];
                var catAdd = Math.round(round.catPropertyAdd * (1 - reduction) * 10) / 10;
                propRes.lossRatio = Math.round((propRes.lossRatio + catAdd) * 10) / 10;
            }

            var reinsCosts = [0, 5, 12];
            var reinsCost = reinsCosts[d.reinsurance || 0];

            var reserveCarry = ds.reserveDeficitCarry || 0;
            var reserveAdj = d.reserveApproach;
            var reserveEffect = 0;
            var nextCarry = 0;
            if (reserveAdj === -1) {
                reserveEffect = -3;
                nextCarry = 4;
            } else if (reserveAdj === 1) {
                reserveEffect = 2;
                nextCarry = -1;
            }

            var expenseRatio = 30;
            var autoCR = autoRes.lossRatio + expenseRatio;
            var propCR = propRes.lossRatio + expenseRatio;
            var liabCR = liabRes.lossRatio + expenseRatio;

            var totalGWP = Math.round((autoRes.newGWP + propRes.newGWP + liabRes.newGWP) * 10) / 10;
            var weightedCR = (autoRes.newGWP * autoCR + propRes.newGWP * propCR + liabRes.newGWP * liabCR) / totalGWP;
            weightedCR += reserveCarry + reserveEffect;
            weightedCR = Math.round(weightedCR * 10) / 10;

            var underwritingResult = Math.round(totalGWP * (1 - weightedCR / 100) * 10) / 10;

            var invStrategy = d.investmentStrategy || 1;
            var yieldRate = round.investYields[invStrategy];
            var floatVal = Math.round((autoRes.newGWP * 0.5 + propRes.newGWP * 1.0 + liabRes.newGWP * 2.5) * 10) / 10;
            var investIncome = Math.round(floatVal * yieldRate * 10) / 10;

            var totalResult = Math.round((underwritingResult + investIncome - reinsCost - d.dividend) * 10) / 10;

            var prevCapital = ds.capital;
            ds.autoGWP = autoRes.newGWP;
            ds.propertyGWP = propRes.newGWP;
            ds.liabilityGWP = liabRes.newGWP;
            ds.totalGWP = totalGWP;
            ds.capital = Math.round((ds.capital + totalResult) * 10) / 10;
            ds.investmentPortfolio = floatVal;
            ds.reserveDeficitCarry = nextCarry;
            ds.lastCombinedRatio = weightedCR;

            var reqCap = ds.autoGWP * 0.15 + ds.propertyGWP * 0.25 + ds.liabilityGWP * 0.35;
            ds.solvencyRatio = Math.round((ds.capital / reqCap) * 100 * 10) / 10;

            var roe = Math.round((totalResult / prevCapital) * 100 * 10) / 10;

            ds.combinedRatioHistory.push(weightedCR);
            ds.capitalHistory.push(ds.capital);
            ds.roeHistory.push(roe);
            ds.investIncomeHistory.push(investIncome);

            // v1.1.0 fix: persist composite where Express reporting reads it.
            // results_utils.php express_resolveDomainScore(): performance.overallScore, then top-level score.
            var composite = this._ipi(ds.combinedRatioHistory, ds.roeHistory, ds.investIncomeHistory, ds.solvencyRatio).ipi;
            ds.score = composite;
            if (!ds.performance || typeof ds.performance !== 'object') ds.performance = {};
            ds.performance.overallScore = composite;

            var results = {
                period: state.currentPeriod,
                autoLossRatio: autoRes.lossRatio,
                propertyLossRatio: propRes.lossRatio,
                liabilityLossRatio: liabRes.lossRatio,
                combinedRatio: weightedCR,
                totalGWP: totalGWP,
                underwritingResult: underwritingResult,
                investmentIncome: investIncome,
                reinsCost: reinsCost,
                totalResult: totalResult,
                capital: ds.capital,
                solvencyRatio: ds.solvencyRatio,
                roe: roe
            };

            var self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return results;
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('capitalDisplay', 'domainState.capital',
                (v) => '$' + Math.round(v).toLocaleString() + 'M');
            uiManager.bind('solvencyDisplay', 'domainState.solvencyRatio',
                (v) => Math.round(v) + '%');
            uiManager.bind('combinedDisplay', 'domainState.lastCombinedRatio',
                (v) => v.toFixed(1) + '%');
            uiManager.bind('gwpDisplay', 'domainState.totalGWP',
                (v) => '$' + Math.round(v).toLocaleString() + 'M');
        }

        getChartConfig() {
            return {
                combinedRatioChart: {
                    type: 'bar',
                    data: {
                        labels: [],
                        datasets: [{
                            label: 'Combined Ratio (%)',
                            data: [],
                            backgroundColor: function(ctx) {
                                var val = ctx.raw;
                                if (val === undefined || val === null) return 'rgba(44,95,138,0.7)';
                                return val > 100 ? 'rgba(231,76,60,0.7)' : 'rgba(39,174,96,0.7)';
                            },
                            borderColor: function(ctx) {
                                var val = ctx.raw;
                                if (val === undefined || val === null) return '#2c5f8a';
                                return val > 100 ? '#c0392b' : '#27ae60';
                            },
                            borderWidth: 2
                        }]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: 'Combined Ratio by Quarter (100% = Break-even)' }
                        },
                        scales: {
                            y: { beginAtZero: false, suggestedMin: 85, suggestedMax: 130 }
                        }
                    }
                },
                capitalChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [{
                            label: 'Capital ($M)',
                            data: [],
                            borderColor: '#1a3a5c',
                            backgroundColor: 'rgba(26,58,92,0.1)',
                            borderWidth: 3,
                            fill: true,
                            tension: 0.2,
                            pointBackgroundColor: '#1a3a5c',
                            pointRadius: 5
                        }]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: 'Capital Evolution ($M)' }
                        },
                        scales: {
                            y: { beginAtZero: false }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            var labels = state.domainState.combinedRatioHistory.map(function(_, i) { return 'Q' + (i + 1); });
            return {
                combinedRatioChart: {
                    labels: labels,
                    datasets: [{ data: state.domainState.combinedRatioHistory }]
                },
                capitalChart: {
                    labels: labels,
                    datasets: [{ data: state.domainState.capitalHistory }]
                }
            };
        }

        _ipi(combinedRatios, roes, investReturns, finalSolvency) {
            var avg = function(a){ return a.length ? a.reduce(function(s,v){ return s + v; }, 0) / a.length : 0; };
            var avgCombined = avg(combinedRatios);
            var avgROE = avg(roes);
            var avgInvReturn = avg(investReturns);
            var roeScore = Math.min(25, Math.max(0, (avgROE / 15) * 25));
            var combinedScore = Math.min(25, Math.max(0, ((110 - avgCombined) / 15) * 25));
            var solvencyScore = Math.min(20, Math.max(0, ((finalSolvency - 100) / 100) * 20));
            var trendScore = 0;
            if (combinedRatios.length >= 2) {
                var improvement = combinedRatios[0] - combinedRatios[combinedRatios.length - 1];
                trendScore = Math.min(15, Math.max(0, (improvement / 15) * 15));
            }
            var investScore = Math.min(10, Math.max(0, (avgInvReturn / 15) * 10));
            var ipi = Math.round(roeScore + combinedScore + solvencyScore + trendScore + investScore);
            return { ipi: ipi, avgCombined: avgCombined, avgROE: avgROE, avgInvReturn: avgInvReturn };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var t = function(k){ return window.mySimulation.t(k); };
            var combinedRatios = history.map(function(r) { return r.results ? r.results.combinedRatio : 100; });
            var roes = history.map(function(r) { return r.results ? r.results.roe : 0; });
            var investReturns = history.map(function(r) { return r.results ? r.results.investmentIncome : 0; });
            var lastRec = history[history.length - 1];
            var finalCapital = lastRec.results ? lastRec.results.capital : 120;
            var finalSolvency = lastRec.results ? lastRec.results.solvencyRatio : 100;

            var m = this._ipi(combinedRatios, roes, investReturns, finalSolvency);
            var totalIPI = m.ipi;

            var performanceId = 'needs_improvement', gradeKey = 'grade_needs';
            if (totalIPI >= 70) { performanceId = 'excellent'; gradeKey = 'grade_excellent'; }
            else if (totalIPI >= 50) { performanceId = 'good'; gradeKey = 'grade_good'; }
            else if (totalIPI >= 30) { performanceId = 'adequate'; gradeKey = 'grade_adequate'; }

            var insights = [];
            if (m.avgCombined < 98) insights.push(t('insight_good_discipline'));
            if (m.avgCombined >= 105) insights.push(t('insight_poor_combined'));
            if (finalSolvency > 180) insights.push(t('insight_strong_capital'));
            if (finalSolvency < 130) insights.push(t('insight_weak_capital'));
            if (m.avgROE > 10) insights.push(t('insight_good_roe'));

            return {
                totalIPI: totalIPI,
                overallScore: totalIPI,
                score: totalIPI,
                avgCombinedRatio: Math.round(m.avgCombined * 10) / 10,
                avgROE: Math.round(m.avgROE * 10) / 10,
                finalCapital: finalCapital,
                finalSolvency: Math.round(finalSolvency * 10) / 10,
                performanceId: performanceId,
                performance: t(gradeKey),
                beatTarget: totalIPI >= 50,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            var t = function(k){ return window.mySimulation.t(k); };
            var s = summary || {};
            var score = (typeof s.totalIPI === 'number') ? s.totalIPI : 0;
            var grade = s.performance || '';
            var beat = !!s.beatTarget;
            var insights = Array.isArray(s.insights) ? s.insights : [];
            var badgeClass = beat ? 'ins-cm-badge-pass' : 'ins-cm-badge-miss';
            var badgeText = beat ? t('cm_badge_beat') : t('cm_badge_missed');
            var kpi = function(label, val){ return '<div class="ins-cm-kpi"><div class="ins-cm-kpi-val">' + val + '</div><div class="ins-cm-kpi-label">' + label + '</div></div>'; };
            var insightHtml = '';
            insights.forEach(function(it){ insightHtml += '<li>' + it + '</li>'; });
            return '' +
              '<div class="ins-cm">' +
                '<div class="ins-cm-scoreblock">' +
                  '<div class="ins-cm-scorenum">' + score + '<span class="ins-cm-scoremax">/100</span></div>' +
                  '<div class="ins-cm-scorelabel">' + t('cm_score_label') + '</div>' +
                  '<div class="ins-cm-grade">' + grade + '</div>' +
                  '<span class="ins-cm-badge ' + badgeClass + '">' + badgeText + '</span>' +
                '</div>' +
                '<div class="ins-cm-kpis">' +
                  kpi(t('cm_combined_label'), (s.avgCombinedRatio != null ? s.avgCombinedRatio : 0) + '%') +
                  kpi(t('cm_roe_label'), (s.avgROE != null ? s.avgROE : 0) + '%') +
                  kpi(t('cm_capital_label'), '$' + Math.round(s.finalCapital || 0) + 'M') +
                  kpi(t('cm_solvency_label'), Math.round(s.finalSolvency || 0) + '%') +
                '</div>' +
                (insightHtml ? '<div class="ins-cm-insights"><h6>' + t('cm_insights_title') + '</h6><ul>' + insightHtml + '</ul></div>' : '') +
                '<div class="ins-cm-footer">' + t('cm_footer') + '</div>' +
              '</div>';
        }

        getHint(state, results) {
            if (!results) return null;
            if (results.combinedRatio > 110) return window.mySimulation.t('hint_high_combined');
            if (results.solvencyRatio < 130) return window.mySimulation.t('hint_low_solvency');
            if (results.combinedRatio < 95 && results.solvencyRatio > 170) return window.mySimulation.t('hint_strong_position');
            if (state.currentPeriod === 2 && results.combinedRatio > 100) return window.mySimulation.t('hint_adverse_selection');
